<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --trigger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cron</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cron</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;0 22 * * *&quot;</span></span>
